('frases',0,'Frases','LA RADIO NOS CONECTA CON NUEVOS AMIGOS.','1'),
('frases',1,'Frases','PUEDES ESCUCHAR EL CANTO DE LOS PAJAROS ESTA MAÑANA?','1'),
('frases',2,'Frases','A LAS 9, JULIA ENCIENDE SU RADIO Y SALUDA A LA ESTACION DEL VALLE.','1'),
('frases',3,'Frases','UN PUNTO, UNA RAYA Y UN POCO DE PACIENCIA NOS AYUDAN A COMPARTIR LAS PALABRAS QUE ANTES PARECIAN MUY DIFICILES.','1'),
('parrafos',0,'Párrafos','LA BIBLIOTECA DEL BARRIO ABRIO UNA PEQUEÑA SALA DE RADIO. CADA SABADO, NIÑAS Y NIÑOS APRENDEN A ESCUCHAR ANTES DE TRANSMITIR. SOBRE LA MESA HAY UN CUADERNO PARA ANOTAR PALABRAS NUEVAS. NADIE TIENE PRISA, PORQUE UNA SEÑAL CLARA VALE MAS QUE UNA SEÑAL RAPIDA.','1'),
('parrafos',1,'Párrafos','EL CAMINO SUBE ENTRE ARBOLES Y TERMINA JUNTO A UNA ESTACION ANTIGUA. ALLI, ELENA OBSERVA UNA FOTOGRAFIA DE SU ABUELO. EL ENVIABA NOTICIAS A LOS PUEBLOS DEL VALLE CUANDO LAS LLUVIAS CORTABAN EL PASO. HOY ELLA APRENDE ESOS MISMOS RITMOS Y ESCRIBE UN MENSAJE SENCILLO. GRACIAS POR ENSEÑARNOS A MANTENER EL CONTACTO.','1'),
('parrafos',2,'Párrafos','DURANTE LA FERIA DE CIENCIAS, NUESTRO GRUPO PREPARO UNA DEMOSTRACION CON LUCES Y SONIDO. AL PRINCIPIO SOLO TRANSMITIMOS NOMBRES CORTOS. DESPUES LLEGARON PREGUNTAS, RESPUESTAS Y HASTA UN PEQUEÑO CUENTO. DESCUBRIMOS QUE EL SILENCIO TAMBIEN LLEVA INFORMACION. UNA PAUSA BREVE UNE LAS SEÑALES DE UNA LETRA Y UNA PAUSA MAYOR SEPARA LAS PALABRAS. CUANDO ALGUIEN SE EQUIVOCABA, REPETIAMOS EL MENSAJE CON CALMA. AL FINAL DE LA TARDE, TODOS HABIAN CONSEGUIDO ENVIAR AL MENOS UNA FRASE COMPLETA SIN MIRAR LA TABLA.','1'),
('textos-largos',0,'Textos largos','LA PRIMERA VEZ QUE INES VISITO EL OBSERVATORIO, PENSO QUE TODAS LAS PREGUNTAS SOBRE EL CIELO TENDRIAN RESPUESTAS ENORMES. SIN EMBARGO, LA PERSONA QUE CUIDABA EL LUGAR LE ENTREGO UN CUADERNO PEQUEÑO Y LE PIDIO QUE ANOTARA LO QUE PODIA VER DESDE LA VENTANA. HABIA UNA NUBE, DOS MONTAÑAS Y UNA LUZ QUE PARPADEABA A LO LEJOS. LA LUZ VENIA DE UNA CASA DONDE VIVIA UN AFICIONADO A LA RADIO. CADA TARDE PRACTICABA MENSAJES BREVES CON UNA AMIGA DEL OTRO LADO DEL VALLE. INES QUISO APRENDER AQUEL LENGUAJE Y COMENZO CON SU NOMBRE. AL PRINCIPIO CONFUNDIA LAS PAUSAS Y OLVIDABA ALGUNA RAYA. SU MAESTRO LE RECORDO QUE ESCUCHAR ERA PARTE DE TRANSMITIR BIEN. DURANTE VARIAS SEMANAS REPITIO PALABRAS, ESCRIBIO PREGUNTAS Y CELEBRO CADA AVANCE PEQUEÑO. UNA NOCHE CONSIGUIO ENVIAR UNA FRASE COMPLETA SOBRE LAS ESTRELLAS QUE ACABABA DE OBSERVAR. LA RESPUESTA LLEGO DESPACIO Y CON CLARIDAD. ALGUIEN, DESDE LA OTRA MONTAÑA, TAMBIEN ESTABA MIRANDO EL CIELO. INES COMPRENDIO ENTONCES QUE APRENDER UN CODIGO NO SOLO SIRVE PARA CAMBIAR LETRAS POR SEÑALES. TAMBIEN ABRE UNA MANERA NUEVA DE COMPARTIR LO QUE NOS ASOMBRA.','1'),
('textos-largos',1,'Textos largos','EN EL PUEBLO DE LOS PUENTES HABIA UNA ESTACION DE RADIO QUE LLEVABA MUCHOS AÑOS CERRADA. SUS VENTANAS MIRABAN HACIA EL RIO Y UNA ENREDADERA CUBRIA PARTE DEL TEJADO. CUANDO EL AYUNTAMIENTO DECIDIO CONVERTIRLA EN UN ESPACIO DE APRENDIZAJE, VARIAS PERSONAS OFRECIERON SU TIEMPO. ALGUNAS LIMPIARON LAS MESAS, OTRAS REPARARON LAS SILLAS Y UN GRUPO DE ESTUDIANTES PREPARO CARTELES PARA DAR LA BIENVENIDA. CLARA ENCONTRO UNA CAJA DE CUADERNOS EN UN ARMARIO. NO CONTENIAN SECRETOS NI TESOROS ESCONDIDOS, SINO REGISTROS DE MENSAJES COTIDIANOS. UN AGRICULTOR AVISABA DE LA LLEGADA DE SEMILLAS. UNA MAESTRA PREGUNTABA POR UNOS LIBROS. UNA FAMILIA ANUNCIABA QUE SU HIJA HABIA NACIDO. CADA PAGINA MOSTRABA COMO UNAS POCAS PALABRAS PODIAN UNIR LUGARES SEPARADOS POR MUCHOS KILOMETROS DE CAMINO. EL PRIMER TALLER REUNIO A DOCE VECINOS. LA PERSONA ENCARGADA EXPLICO QUE EL CODIGO MORSE COMBINA SEÑALES CORTAS, SEÑALES LARGAS Y SILENCIOS. DIBUJO UN PUNTO Y UNA RAYA, PERO PIDIO QUE NADIE INTENTARA MEMORIZAR TODA LA TABLA AQUELLA TARDE. EMPEZARON CON DOS LETRAS, ESCUCHARON SUS RITMOS Y LUEGO CAMBIARON DE PAPEL. QUIEN HABIA TRANSMITIDO DEBIA AHORA RECIBIR EL MENSAJE DE SU COMPAÑERO. HUBO RISAS CUANDO UNA PALABRA SE CONVIRTIO EN OTRA. CLARA ESCRIBIO LUNA DONDE SU AMIGO QUERIA DECIR LUPA. REVISARON JUNTOS LA DIFERENCIA Y DESCUBRIERON QUE UNA SOLA SEÑAL CAMBIABA LA LETRA FINAL. EL ERROR QUEDO ANOTADO EN EL CUADERNO COMO PARTE DEL APRENDIZAJE. EN EL SIGUIENTE INTENTO AMBOS REDUJERON LA VELOCIDAD Y PRESTARON MAS ATENCION A LAS PAUSAS ENTRE LETRAS. CON EL PASO DE LAS SEMANAS, LOS EJERCICIOS CRECIERON. PRIMERO FUERON NOMBRES, DESPUES FRASES Y FINALMENTE RELATOS COMPLETOS. CADA PARTICIPANTE PODIA AJUSTAR LOS TIEMPOS PARA SENTIRSE COMODO. UNA NIÑA PREFERIA ESCUCHAR SIN MIRAR LA PANTALLA. SU ABUELO NECESITABA VER LAS SEÑALES ANTES DE RECONOCERLAS POR EL SONIDO. NINGUNO TENIA QUE SEGUIR EXACTAMENTE EL MISMO RITMO PARA APRENDER JUNTO AL OTRO. UNA TARDE DE LLUVIA PREPARARON UNA ACTIVIDAD ESPECIAL. CADA PAREJA RECIBIO UNA HISTORIA DIFERENTE Y DEBIA TRANSMITIRLA POR PARTES. AL TERMINAR UNA ORACION, REVISABAN LA RESPUESTA Y DESCANSABAN UNOS SEGUNDOS. ASI EVITARON QUE EL CANSANCIO ESCONDIERA LO QUE YA SABIAN. TAMBIEN DESCUBRIERON QUE TERMINAR DEPRISA NO SIEMPRE SIGNIFICABA COMUNICAR MEJOR. LA CLARIDAD PERMITIA QUE LA HISTORIA CONSERVARA TODOS SUS DETALLES. CLARA ELIGIO CONTAR EL VIAJE DE UNA SEMILLA DESDE LA MONTAÑA HASTA EL JARDIN DE UNA ESCUELA. SU COMPAÑERO ESCUCHO CON PACIENCIA Y ESCRIBIO CADA FRAGMENTO. CUANDO LLEGARON AL FINAL, COMPARARON EL TEXTO COMPLETO. FALTABA UNA COMA Y SOBRABA UNA LETRA, PERO EL RECORRIDO SEGUIA SIENDO FACIL DE ENTENDER. REPITIERON LOS DOS SEGMENTOS Y GUARDARON AMBOS INTENTOS PARA RECORDAR CUANTO HABIAN AVANZADO. AL CERRAR LA ESTACION, DEJARON UN CARTEL JUNTO A LA PUERTA. INVITABA A CUALQUIER PERSONA A ENTRAR, ESCUCHAR Y PROBAR. LOS CUADERNOS ANTIGUOS PERMANECIERON EN UNA ESTANTERIA, JUNTO A LOS NUEVOS. ENTRE SUS PAGINAS CONVIVIAN NOTICIAS DEL PASADO Y PREGUNTAS DEL PRESENTE. LA ESTACION VOLVIA A CUMPLIR SU TAREA MAS SENCILLA, OFRECER UN LUGAR DONDE ALGUIEN PUDIERA ENVIAR UNA IDEA Y ENCONTRAR AL OTRO LADO A ALGUIEN DISPUESTO A RECIBIRLA.','1')
